     1|/**
     2| * IVX Autonomous Dashboard — live W1–W12 job ledger (owner-only).
     3| *
     4| * Reads REAL production data from:
     5| *   GET https://api.ivxholding.com/api/ivx/autonomous/ledger
     6| *
     7| * No seed data: every job shown carries a stable job ID, status history with
     8| * timestamps, evidence, and blockers straight from the durable backend ledger.
     9| * Auto-refreshes via controlled polling (30s) + pull-to-refresh.
    10| */
    11|import React, { useState, useCallback, useEffect, useRef } from 'react';
    12|import {
    13|  View,
    14|  Text,
    15|  StyleSheet,
    16|  ScrollView,
    17|  TouchableOpacity,
    18|  ActivityIndicator,
    19|  RefreshControl,
    20|} from 'react-native';
    21|import { SafeAreaView } from 'react-native-safe-area-context';
    22|import { Stack, useRouter } from 'expo-router';
    23|import {
    24|  Activity,
    25|  AlertTriangle,
    26|  ArrowLeft,
    27|  CheckCircle2,
    28|  ChevronDown,
    29|  ChevronRight,
    30|  Clock,
    31|  Cpu,
    32|  ListChecks,
    33|  Lock,
    34|  RefreshCw,
    35|  ShieldCheck,
    36|} from 'lucide-react-native';
    37|import { getIVXAccessToken } from '@/lib/ivx-supabase-client';
    38|
    39|const API_BASE = (process.env.EXPO_PUBLIC_IVX_API_BASE_URL || 'https://api.ivxholding.com').replace(/\/+$/, '');
    40|const LEDGER_URL = `${API_BASE}/api/ivx/autonomous/ledger`;
    41|const GUARDIAN_URL = `${API_BASE}/api/ivx/autonomous/auth-guardian`;
    42|const QA_URL = `${API_BASE}/api/ivx/autonomous/qa`;
    43|const CREDENTIALS_URL = `${API_BASE}/api/ivx/autonomous/credentials`;
    44|const EXECUTIVE_URL = `${API_BASE}/api/ivx/executive-layer`;
    45|const RUNS_URL = `${API_BASE}/api/ivx/autonomous/runs`;
    46|const RUNS_SUMMARY_URL = `${API_BASE}/api/ivx/autonomous/runs/summary`;
    47|const POLL_INTERVAL_MS = 15_000;
    48|
    49|type LedgerWorker = { id: string; name: string; scope: string };
    50|
    51|type LedgerHistoryEntry = { at: string; from: string | null; to: string; note: string | null };
    52|
    53|type LedgerJob = {
    54|  jobId: string;
    55|  workerId: string;
    56|  title: string;
    57|  status: string;
    58|  priority: string;
    59|  evidence: string | null;
    60|  blocker: string | null;
    61|  createdAt: string;
    62|  updatedAt: string;
    63|  history: LedgerHistoryEntry[];
    64|};
    65|
    66|type LedgerApproval = {
    67|  approvalId: string;
    68|  workerId: string;
    69|  title: string;
    70|  risk: string;
    71|  rollback: string;
    72|  status: string;
    73|  createdAt: string;
    74|};
    75|
    76|type LedgerCounts = {
    77|  workers: number;
    78|  jobs: number;
    79|  verified: number;
    80|  running: number;
    81|  blocked: number;
    82|  ownerActionRequired: number;
    83|  queued: number;
    84|  pendingApprovals: number;
    85|};
    86|
    87|type GuardianProbe = {
    88|  id: string;
    89|  name: string;
    90|  target: string;
    91|  ok: boolean;
    92|  httpStatus: number | null;
    93|  latencyMs: number;
    94|  detail: string;
    95|  checkedAt: string;
    96|};
    97|
    98|type GuardianIncident = {
    99|  incidentId: string;
   100|  probeId: string;
   101|  openedAt: string;
   102|  closedAt: string | null;
   103|  status: string;
   104|  detail: string;
   105|};
   106|
   107|type GuardianAlert = {
   108|  alertId: string;
   109|  severity: string;
   110|  area: string;
   111|  problem: string;
   112|  smsStatus: string;
   113|  messageId: string | null;
   114|  toMasked: string;
   115|  sentAt: string;
   116|  test: boolean;
   117|};
   118|
   119|type GuardianSmsProvider = {
   120|  provider?: string;
   121|  awsCredentialsConfigured?: boolean;
   122|  awsRegion?: string;
   123|  ownerPhoneResolved?: boolean;
   124|  ownerPhoneMasked?: string | null;
   125|  phoneSource?: string;
   126|  ready?: boolean;
   127|};
   128|
   129|type GuardianResponse = {
   130|  ok: boolean;
   131|  error?: string;
   132|  marker?: string;
   133|  generatedAt?: string;
   134|  totalRuns?: number;
   135|  overall?: string;
   136|  probes?: GuardianProbe[];
   137|  openIncidents?: GuardianIncident[];
   138|  recentIncidents?: GuardianIncident[];
   139|  smsProvider?: GuardianSmsProvider;
   140|  recentAlerts?: GuardianAlert[];
   141|};
   142|
   143|type QARunEntry = {
   144|  runId: string;
   145|  kind: string;
   146|  at: string;
   147|  ok: boolean;
   148|  summary: string;
   149|};
   150|
   151|type QAResponse = {
   152|  ok: boolean;
   153|  error?: string;
   154|  marker?: string;
   155|  schedulerRunning?: boolean;
   156|  cadence?: { healthMinutes?: number; authMinutes?: number; matrixHours?: number };
   157|  lastHealthAt?: string | null;
   158|  lastAuthAt?: string | null;
   159|  lastMatrixAt?: string | null;
   160|  healthOk?: boolean | null;
   161|  authOk?: boolean | null;
   162|  totalRuns?: number;
   163|  recentRuns?: QARunEntry[];
   164|};
   165|
   166|type CredentialRow = {
   167|  service: string;
   168|  variable: string;
   169|  environment: string;
   170|  stored: boolean;
   171|  injected: boolean;
   172|  authenticated: boolean | null;
   173|  permissionTest: string;
   174|  runtimeTest: string;
   175|  httpStatus: number | null;
   176|  securityCheck: string;
   177|  blocker: string | null;
   178|  worker: string;
   179|  finalStatus: string;
   180|  testedAt: string;
   181|};
   182|
   183|type CredentialsResponse = {
   184|  ok: boolean;
   185|  error?: string;
   186|  marker?: string;
   187|  generatedAt?: string;
   188|  totalRuns?: number;
   189|  totals?: { total: number; verified: number; partial: number; blocked: number };
   190|  credentials?: CredentialRow[];
   191|};
   192|
   193|type LedgerResponse = {
   194|  ok: boolean;
   195|  error?: string;
   196|  marker?: string;
   197|  generatedAt?: string;
   198|  version?: number;
   199|  updatedAt?: string;
   200|  counts?: LedgerCounts;
   201|  workers?: LedgerWorker[];
   202|  jobs?: LedgerJob[];
   203|  approvals?: LedgerApproval[];
   204|};
   205|
   206|type EngineAction = {
   207|  kind: string;
   208|  label: string;
   209|  status: string;
   210|  lastRunAt: string;
   211|  runCount: number;
   212|  summary: string;
   213|};
   214|
   215|type AutonomousActionsView = {
   216|  schedulerEnabled: boolean;
   217|  totalRuns: number;
   218|  runsWithEvidence: number;
   219|  runsWithoutEvidence: number;
   220|  loopsRun: number;
   221|  outcomesRecorded: number;
   222|  actions: EngineAction[];
   223|};
   224|
   225|type ExecutiveResponse = {
   226|  ok: boolean;
   227|  error?: string;
   228|  executive?: {
   229|    autonomousActions?: AutonomousActionsView;
   230|  };
   231|};
   232|
   233|type RunRecord = {
   234|  runId: string;
   235|  kind: string;
   236|  engine: string | null;
   237|  workerId: string;
   238|  startedAt: string;
   239|  finishedAt: string;
   240|  durationMs: number;
   241|  status: string;
   242|  recordsDiscovered: number;
   243|  recordsInserted: number;
   244|  recordsUpdated: number;
   245|  duplicatesSkipped: number;
   246|  outreachQueued: number;
   247|  sendingEnabled: boolean;
   248|  error: string | null;
   249|  summary: string;
   250|  source: string;
   251|  evidence: string[];
   252|  hasEvidence: boolean;
   253|  commitSha: string | null;
   254|  deploymentSha: string | null;
   255|  marker: string;
   256|};
   257|
   258|type RunsSummary = {
   259|  ok: boolean;
   260|  totalRuns: number;
   261|  runsWithEvidence: number;
   262|  runsWithoutEvidence: number;
   263|  failed: number;
   264|  byEngine?: Array<{ kind: string; engine: string | null; runCount: number; lastRunAt: string | null; lastStatus: string | null; lastSummary: string | null; withEvidence: number }>;
   265|  note?: string;
   266|};
   267|
   268|const STATUS_COLORS: Record<string, string> = {
   269|  VERIFIED: '#34D399',
   270|  DONE: '#34D399',
   271|  RUNNING: '#FBBF24',
   272|  QUEUED: '#94A3B8',
   273|  BLOCKED: '#F87171',
   274|  OWNER_ACTION_REQUIRED: '#F97316',
   275|};
   276|
   277|const STATUS_ORDER: string[] = ['RUNNING', 'BLOCKED', 'OWNER_ACTION_REQUIRED', 'QUEUED', 'VERIFIED', 'DONE'];
   278|
   279|function statusColor(status: string): string {
   280|  return STATUS_COLORS[status] ?? '#94A3B8';
   281|}
   282|
   283|function formatTime(iso: string | null | undefined): string {
   284|  if (!iso) return '—';
   285|  try {
   286|    const d = new Date(iso);
   287|    return `${d.toISOString().slice(0, 10)} ${d.toISOString().slice(11, 16)} UTC`;
   288|  } catch {
   289|    return iso;
   290|  }
   291|}
   292|
   293|export default function AutonomousDashboardScreen() {
   294|  const router = useRouter();
   295|  const [data, setData] = useState<LedgerResponse | null>(null);
   296|  const [isLoading, setIsLoading] = useState<boolean>(true);
   297|  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
   298|  const [errorMessage, setErrorMessage] = useState<string | null>(null);
   299|  const [isUnauthorized, setIsUnauthorized] = useState<boolean>(false);
   300|  const [expandedJobId, setExpandedJobId] = useState<string | null>(null);
   301|  const [lastFetchedAt, setLastFetchedAt] = useState<string | null>(null);
   302|  const [guardian, setGuardian] = useState<GuardianResponse | null>(null);
   303|  const [qa, setQa] = useState<QAResponse | null>(null);
   304|  const [creds, setCreds] = useState<CredentialsResponse | null>(null);
   305|  const [executive, setExecutive] = useState<ExecutiveResponse | null>(null);
   306|  const [runs, setRuns] = useState<RunRecord[]>([]);
   307|  const [runsSummary, setRunsSummary] = useState<RunsSummary | null>(null);
   308|  const [expandedRunId, setExpandedRunId] = useState<string | null>(null);
   309|  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
   310|
   311|  const fetchLedger = useCallback(async (silent: boolean) => {
   312|    if (!silent) setIsLoading(true);
   313|    setErrorMessage(null);
   314|    try {
   315|      const token = await getIVXAccessToken();
   316|      if (!token) {
   317|        setIsUnauthorized(true);
   318|        setErrorMessage('Owner session required. Sign in as the owner to view the autonomous ledger.');
   319|        return;
   320|      }
   321|      const response = await fetch(LEDGER_URL, {
   322|        method: 'GET',
   323|        headers: { Authorization: `Bearer ${token}` },
   324|      });
   325|      if (response.status === 401 || response.status === 403) {
   326|        setIsUnauthorized(true);
   327|        setErrorMessage('Access denied: this dashboard is restricted to the IVX owner.');
   328|        return;
   329|      }
   330|      const json = (await response.json()) as LedgerResponse;
   331|      if (!json.ok) {
   332|        setErrorMessage(json.error ?? `Ledger request failed (HTTP ${response.status}).`);
   333|        return;
   334|      }
   335|      setIsUnauthorized(false);
   336|      setData(json);
   337|      setLastFetchedAt(new Date().toISOString());
   338|      try {
   339|        const [guardianResponse, qaResponse, credsResponse, execResponse, runsResponse, runsSummaryResponse] = await Promise.all([
   340|          fetch(GUARDIAN_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   341|          fetch(QA_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   342|          fetch(CREDENTIALS_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   343|          fetch(EXECUTIVE_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   344|          fetch(`${RUNS_URL}?limit=50`, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   345|          fetch(RUNS_SUMMARY_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   346|        ]);
   347|        if (guardianResponse.ok) {
   348|          const guardianJson = (await guardianResponse.json()) as GuardianResponse;
   349|          if (guardianJson.ok) setGuardian(guardianJson);
   350|        }
   351|        if (qaResponse.ok) {
   352|          const qaJson = (await qaResponse.json()) as QAResponse;
   353|          if (qaJson.ok) setQa(qaJson);
   354|        }
   355|        if (credsResponse.ok) {
   356|          const credsJson = (await credsResponse.json()) as CredentialsResponse;
   357|          if (credsJson.ok) setCreds(credsJson);
   358|        }
   359|        if (execResponse.ok) {
   360|          const execJson = (await execResponse.json()) as ExecutiveResponse;
   361|          if (execJson.ok) setExecutive(execJson);
   362|        }
   363|        if (runsResponse.ok) {
   364|          const runsJson = (await runsResponse.json()) as { ok: boolean; runs?: RunRecord[] };
   365|          if (runsJson.ok && Array.isArray(runsJson.runs)) setRuns(runsJson.runs);
   366|        }
   367|        if (runsSummaryResponse.ok) {
   368|          const summaryJson = (await runsSummaryResponse.json()) as RunsSummary;
   369|          if (summaryJson.ok) setRunsSummary(summaryJson);
   370|        }
   371|      } catch (guardianError) {
   372|        console.log('[AutonomousDashboard] guardian/qa fetch skipped:', guardianError instanceof Error ? guardianError.message : guardianError);
   373|      }
   374|    } catch (err) {
   375|      const message = err instanceof Error ? err.message : 'Network error loading ledger.';
   376|      console.log('[AutonomousDashboard] fetch failed:', message);
   377|      setErrorMessage(message);
   378|    } finally {
   379|      setIsLoading(false);
   380|      setIsRefreshing(false);
   381|    }
   382|  }, []);
   383|
   384|  useEffect(() => {
   385|    fetchLedger(false);
   386|    pollRef.current = setInterval(() => fetchLedger(true), POLL_INTERVAL_MS);
   387|    return () => {
   388|      if (pollRef.current) clearInterval(pollRef.current);
   389|    };
   390|  }, [fetchLedger]);
   391|
   392|  const onRefresh = useCallback(() => {
   393|    setIsRefreshing(true);
   394|    fetchLedger(true);
   395|  }, [fetchLedger]);
   396|
   397|  const counts = data?.counts;
   398|  const jobs = data?.jobs ?? [];
   399|  const workers = data?.workers ?? [];
   400|  const approvals = (data?.approvals ?? []).filter((a) => a.status === 'PENDING');
   401|  const sortedJobs = [...jobs].sort((a, b) => {
   402|    const sa = STATUS_ORDER.indexOf(a.status);
   403|    const sb = STATUS_ORDER.indexOf(b.status);
   404|    if (sa !== sb) return sa - sb;
   405|    return a.jobId.localeCompare(b.jobId);
   406|  });
   407|  const completionPercent = counts && counts.jobs > 0 ? Math.round((counts.verified / counts.jobs) * 100) : 0;
   408|
   409|  return (
   410|    <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
   411|      <Stack.Screen options={{ headerShown: false }} />
   412|      <View style={styles.header}>
   413|        <TouchableOpacity onPress={() => router.back()} style={styles.backButton} testID="autonomous-dashboard-back">
   414|          <ArrowLeft size={22} color="#E2E8F0" />
   415|        </TouchableOpacity>
   416|        <View style={styles.headerTitleWrap}>
   417|          <Text style={styles.headerTitle}>Autonomous Dashboard</Text>
   418|          <Text style={styles.headerSubtitle}>
   419|            Live ledger · v{data?.version ?? '—'} · {formatTime(lastFetchedAt)}
   420|          </Text>
   421|        </View>
   422|        <TouchableOpacity onPress={onRefresh} style={styles.refreshButton} testID="autonomous-dashboard-refresh">
   423|          <RefreshCw size={18} color="#FBBF24" />
   424|        </TouchableOpacity>
   425|      </View>
   426|
   427|      {isLoading ? (
   428|        <View style={styles.centerFill}>
   429|          <ActivityIndicator size="large" color="#FBBF24" />
   430|          <Text style={styles.loadingText}>Loading live job ledger…</Text>
   431|        </View>
   432|      ) : isUnauthorized ? (
   433|        <View style={styles.centerFill}>
   434|          <Lock size={40} color="#F87171" />
   435|          <Text style={styles.errorTitle}>Owner access required</Text>
   436|          <Text style={styles.errorBody}>{errorMessage}</Text>
   437|        </View>
   438|      ) : errorMessage && !data ? (
   439|        <View style={styles.centerFill}>
   440|          <AlertTriangle size={40} color="#F87171" />
   441|          <Text style={styles.errorTitle}>Could not load ledger</Text>
   442|          <Text style={styles.errorBody}>{errorMessage}</Text>
   443|          <TouchableOpacity style={styles.retryButton} onPress={() => fetchLedger(false)}>
   444|            <Text style={styles.retryText}>Retry</Text>
   445|          </TouchableOpacity>
   446|        </View>
   447|      ) : (
   448|        <ScrollView
   449|          style={styles.scroll}
   450|          contentContainerStyle={styles.scrollContent}
   451|          refreshControl={<RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} tintColor="#FBBF24" />}
   452|        >
   453|          {counts ? (
   454|            <View style={styles.card}>
   455|              <View style={styles.cardHeaderRow}>
   456|                <Activity size={16} color="#FBBF24" />
   457|                <Text style={styles.cardHeader}>Overview</Text>
   458|              </View>
   459|              <View style={styles.progressTrack}>
   460|                <View style={[styles.progressFill, { width: `${completionPercent}%` }]} />
   461|              </View>
   462|              <Text style={styles.progressLabel}>{completionPercent}% verified ({counts.verified}/{counts.jobs} jobs)</Text>
   463|              <View style={styles.statGrid}>
   464|                <StatPill label="Running" value={counts.running} color="#FBBF24" />
   465|                <StatPill label="Blocked" value={counts.blocked} color="#F87171" />
   466|                <StatPill label="Owner action" value={counts.ownerActionRequired} color="#F97316" />
   467|                <StatPill label="Queued" value={counts.queued} color="#94A3B8" />
   468|                <StatPill label="Workers" value={counts.workers} color="#60A5FA" />
   469|                <StatPill label="Approvals" value={counts.pendingApprovals} color="#F97316" />
   470|              </View>
   471|            </View>
   472|          ) : null}
   473|
   474|          {executive?.executive?.autonomousActions ? (
   475|            <View style={styles.card}>
   476|              <View style={styles.cardHeaderRow}>
   477|                <Activity size={16} color="#34D399" />
   478|                <Text style={styles.cardHeader}>Live Engine Runs</Text>
   479|                <Text style={[styles.guardianBadge, { color: executive.executive.autonomousActions.schedulerEnabled ? '#34D399' : '#F87171' }]}>
   480|                  {executive.executive.autonomousActions.schedulerEnabled ? 'SCHEDULER ON' : 'SCHEDULER OFF'}
   481|                </Text>
   482|              </View>
   483|              <Text style={styles.guardianMeta}>
   484|                {executive.executive.autonomousActions.totalRuns} total runs · {executive.executive.autonomousActions.runsWithEvidence} with evidence · {executive.executive.autonomousActions.runsWithoutEvidence} without · {executive.executive.autonomousActions.loopsRun} loops
   485|              </Text>
   486|              {(executive.executive.autonomousActions.actions ?? []).map((action) => (
   487|                <View key={action.kind} style={styles.probeRow}>
   488|                  <View style={[styles.statusDot, { backgroundColor: action.status === 'ok' ? '#34D399' : action.status === 'blocked' ? '#F87171' : '#FBBF24' }]} />
   489|                  <View style={styles.probeTextWrap}>
   490|                    <Text style={styles.probeName}>{action.label}</Text>
   491|                    <Text style={styles.probeDetail}>
   492|                      {action.runCount} runs · {formatTime(action.lastRunAt)}
   493|                    </Text>
   494|                    <Text style={styles.probeDetail}>{action.summary}</Text>
   495|                  </View>
   496|                </View>
   497|              ))}
   498|            </View>
   499|          ) : null}
   500|
   501|          {runsSummary ? (
   502|            <View style={styles.card}>
   503|              <View style={styles.cardHeaderRow}>
   504|                <ListChecks size={16} color="#34D399" />
   505|                <Text style={styles.cardHeader}>Permanent Run Evidence</Text>
   506|                <Text style={[styles.guardianBadge, { color: runsSummary.runsWithoutEvidence === 0 ? '#34D399' : '#FBBF24' }]}>
   507|                  {runsSummary.runsWithEvidence}/{runsSummary.totalRuns} EVIDENCED
   508|                </Text>
   509|              </View>
   510|              <Text style={styles.guardianMeta}>
   511|                {runsSummary.totalRuns} permanent records · {runsSummary.runsWithEvidence} with evidence · {runsSummary.runsWithoutEvidence} without · {runsSummary.failed} failed · survives restarts/deploys
   512|              </Text>
   513|              {(runsSummary.byEngine ?? []).map((eng) => (
   514|                <View key={eng.kind} style={styles.probeRow}>
   515|                  <View style={[styles.statusDot, { backgroundColor: eng.lastStatus === 'ok' ? '#34D399' : '#F87171' }]} />
   516|                  <View style={styles.probeTextWrap}>
   517|                    <Text style={styles.probeName}>{eng.kind.replace('daily_', '').replace(/_/g, ' ')}</Text>
   518|                    <Text style={styles.probeDetail}>
   519|                      {eng.runCount} run(s) · {eng.withEvidence} evidenced · last {formatTime(eng.lastRunAt)}
   520|                    </Text>
   521|                    {eng.lastSummary ? <Text style={styles.probeDetail}>{eng.lastSummary}</Text> : null}
   522|                  </View>
   523|                </View>
   524|              ))}
   525|              {runsSummary.note ? <Text style={styles.jobEvidence}>{runsSummary.note}</Text> : null}
   526|            </View>
   527|          ) : null}
   528|
   529|          {runs.length > 0 ? (
   530|            <View style={styles.card}>
   531|              <View style={styles.cardHeaderRow}>
   532|                <Clock size={16} color="#60A5FA" />
   533|                <Text style={styles.cardHeader}>Historical Executions ({runs.length})</Text>
   534|                <Text style={[styles.guardianBadge, { color: '#60A5FA' }]}>NEWEST FIRST</Text>
   535|              </View>
   536|              <Text style={styles.guardianMeta}>
   537|                Tap any run to inspect full evidence (records, source URLs, commit/deploy SHA, errors).
   538|              </Text>
   539|              {runs.map((run) => {
   540|                const expanded = expandedRunId === run.runId;
   541|                return (
   542|                  <TouchableOpacity
