   127| */
   128|export async function loadAgentRegistry(): Promise<Map<string, AgentRegistryRecord>> {
   129|  if (inMemoryRegistry) return inMemoryRegistry;
   130|
   131|  const registry = new Map<string, AgentRegistryRecord>();
   132|
   133|  try {
   134|    let raw: string;
   135|    if (isDurableStoreConfigured()) {
   136|      const data = await readDurableJson<AgentRegistryRecord[]>(REGISTRY_PATH, []);
   137|      raw = JSON.stringify(data);
   138|    } else {
   139|      raw = await readFile(REGISTRY_PATH, 'utf8');
   140|    }
   141|    const records: AgentRegistryRecord[] = JSON.parse(raw);
   142|    for (const record of records) {
   143|      if (record && typeof record.agent_id === 'string') {
   144|        registry.set(record.agent_id, record);
   145|      }
   146|    }
   147|  } catch {
