   304|export type RegistryValidationResult = {
   305|  ok: boolean;
   306|  errors: string[];
   307|  warnings: string[];
   308|  agentCount: number;
   309|  expectedCount: number;
   310|};
   311|
   312|/**
   313| * Validate the agent registry against the required rules.
   314| *
   315| * Rules:
   316| * - agents.length must equal expected registry count
   317| * - every required agent must have a unique ID
   318| * - every required role must exist
   319| * - every required test must have execution evidence
   320| * - zero agents must return FAIL
   321| * - missing evidence must return FAIL
   322| * - shared worker must be labeled SHARED WORKER, not independent agent
   323| * - no score may be based only on declared tools
   324| */
   325|export async function validateAgentRegistry(
   326|  expectedAgentIds: string[],
   327|  requiredRoles: string[],
   328|): Promise<RegistryValidationResult> {
   329|  const errors: string[] = [];
   330|  const warnings: string[] = [];
   331|  const registry = await loadAgentRegistry();
   332|  const records = Array.from(registry.values());
   333|
   334|  // Rule: zero agents → FAIL (but still check for missing agents)
   335|  if (records.length === 0 && expectedAgentIds.length > 0) {
   336|    errors.push('Registry is empty — zero agents registered. FAIL.');
   337|    // Don't return early — also report missing agents for complete diagnostics
   338|    for (const expectedId of expectedAgentIds) {
   339|      errors.push(`Missing required agent: ${expectedId}`);
   340|    }
   341|    return { ok: false, errors, warnings, agentCount: 0, expectedCount: expectedAgentIds.length };
   342|  }
   343|
   344|  // Rule: agents.length must equal expected registry count
   345|  if (records.length !== expectedAgentIds.length) {
   346|    errors.push(
   347|      `Agent count mismatch: registry has ${records.length}, expected ${expectedAgentIds.length}`,
   348|    );
   349|  }
   350|
   351|  // Rule: every required agent must have a unique ID
   352|  const ids = records.map((r) => r.agent_id);
   353|  const duplicates = ids.filter((id, idx) => ids.indexOf(id) !== idx);
   354|  if (duplicates.length > 0) {
   355|    errors.push(`Duplicate agent IDs found: ${duplicates.join(', ')}`);
   356|  }
   357|
   358|  // Rule: every required agent must be present
   359|  for (const expectedId of expectedAgentIds) {
   360|    if (!registry.has(expectedId)) {
   361|      errors.push(`Missing required agent: ${expectedId}`);
   362|    }
   363|  }
   364|
   365|  // Rule: every required role must exist
   366|  const presentRoles = records.map((r) => r.role);
   367|  for (const requiredRole of requiredRoles) {
   368|    if (!presentRoles.some((r) => r.includes(requiredRole))) {
   369|      errors.push(`Missing required role: ${requiredRole}`);
   370|    }
   371|  }
   372|
   373|  // Rule: shared worker must be labeled SHARED_WORKER, not independent
   374|  for (const record of records) {
   375|    if (record.runtime_type === 'shared_worker' && record.classification === 'REAL_INDEPENDENT_AGENT') {
   376|      errors.push(
   377|        `Agent ${record.agent_id} runs on a shared worker but is mislabeled REAL_INDEPENDENT_AGENT`,
   378|      );
   379|    }
   380|    if (record.runtime_type === 'config_only' && record.classification === 'REAL_INDEPENDENT_AGENT') {
   381|      errors.push(
   382|        `Agent ${record.agent_id} has no runtime but is mislabeled REAL_INDEPENDENT_AGENT`,
   383|      );
   384|    }
   385|  }
   386|
   387|  // Rule: every agent must have a heartbeat or be marked never_started
   388|  for (const record of records) {
   389|    if (record.status === 'online' && !record.heartbeat) {
   390|      errors.push(`Agent ${record.agent_id} is online but has no heartbeat`);
   391|    }
   392|    if (record.classification === 'REAL_INDEPENDENT_AGENT' && !record.heartbeat) {
   393|      warnings.push(`Agent ${record.agent_id} is classified independent but has no heartbeat`);
   394|    }
   395|  }
   396|
   397|  // Rule: every agent must have at least one completed job or be marked never_started
   398|  for (const record of records) {
   399|    if (
   400|      record.classification === 'REAL_INDEPENDENT_AGENT' &&
   401|      !record.last_completed_job &&
   402|      record.status !== 'never_started'
   403|    ) {
   404|      warnings.push(
   405|        `Agent ${record.agent_id} is classified independent but has no completed job`,
   406|      );
   407|    }
   408|  }
   409|
   410|  // Rule: no score may be based only on declared tools
   411|  // (This is enforced in the audit module, not here — but we check that
   412|  // capabilities have verified=true with evidence)
   413|  for (const record of records) {
   414|    for (const cap of record.capabilities) {
   415|      if (cap.required && !cap.verified) {
   416|        warnings.push(
   417|          `Agent ${record.agent_id} capability "${cap.name}" is required but not verified`,
   418|        );
   419|      }
   420|    }
   421|  }
   422|
   423|  return {
   424|    ok: errors.length === 0,
   425|    errors,
   426|    warnings,
   427|    agentCount: records.length,
   428|    expectedCount: expectedAgentIds.length,
   429|  };
