            </Text>
            <Text style={stats.stylesLabel}>High Risk</Text>
          </View>
        </View>

        {/* Search */}
        <View style={styles.searchContainer}>
          <Search color={Colors.mutedGray} size={18} strokeWidth={2} />
          <TextInput
            style={styles.searchInput}
            placeholder="Search agents, tools, domains..."
